// Сводка Задачи человеку на польском: её читают сотрудники Заказчика. Последнее Сообщение Клиента —
// как есть, на его языке; ссылка на Беседу — родитель задачи в CRM.
const CHANNELS = { messenger: 'Messenger', instagram: 'Instagram', whatsapp: 'WhatsApp', call: 'Telefon' };
const LEAD_LABELS = { name: 'Imię', contact: 'Kontakt', service: 'Usługa', description: 'Opis', desired_date: 'Termin' };
const lead = $json;
const client = lead.name || `${CHANNELS[lead.channel]} · ${lead.sender_id}`;
const known = Object.entries(LEAD_LABELS).filter(([field]) => lead[field]).map(([field, label]) => `${label}: ${lead[field]}`);
const description = [
  `Powód: ${lead.handoff_reason || 'klient prosi o kontakt z człowiekiem'}`,
  `Kanał: ${CHANNELS[lead.channel]}`,
  ...known,
  `Ostatnia wiadomość klienta: ${lead.last_message}`,
].join('\n');
return { json: { name: `Przekazanie rozmowy: ${client}`, description } };
